slots.VIEW:
SIM = {
  duration: 3,
  bodies: [
    { id: "piston", at: function (s) { const b = s.piston; return [b.x, b.y]; } }
  ],
  phases: [{ t0: 0, t1: 1 }, { t0: 1, t1: 2 }, { t0: 2, t1: 3 }],
};

slots.stateAt:
// 由 analysis 运动表生成；不要手改
const state = {};
let tt0 = t;
if (tt0 < 0) tt0 = 0;
if (tt0 > 3) tt0 = 3;
let x0, y0;
if (tt0 <= 1) { x0 = 0 + 0*(tt0 - 0); y0 = 1.11 + -0.1*(tt0 - 0); }
else if (tt0 <= 2) { x0 = 0; y0 = 1.01; }
else if (tt0 <= 3) { x0 = 0; y0 = 1.01; }
else { x0 = 0; y0 = 1.01; }
state.piston = { x: x0, y: y0, type: "piston" };
return state;

slots.drawFrame:
const px = state.piston.x;
const py = state.piston.y;
const hw = 0.25;      // 汽缸内半宽
const topY = 1.55;    // 缸口高度

// 汽缸（静态容器）：两侧缸壁 + 缸底 c
Draw.line([-hw, 0], [-hw, topY], { width: 3 });
Draw.line([hw, 0], [hw, topY], { width: 3 });
Draw.line([-hw, 0], [hw, 0], { width: 3 });

// 卡销 a（上）与卡销 b（下），固定在缸壁上
Draw.box([-hw + 0.03, 1.09], 0.06, 0.02);
Draw.box([hw - 0.03, 1.09], 0.06, 0.02);
Draw.box([-hw + 0.03, 0.99], 0.06, 0.02);
Draw.box([hw - 0.03, 0.99], 0.06, 0.02);

// 轻质活塞：水平置于缸内，随 state 上下移动
Draw.box([px, py], 2 * hw - 0.02, 0.02);

// 竖直向下的外力
Draw.arrow([px, py + 0.30], [0, -0.14], { category: "force", mag: 200 });

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(3, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "piston.x", label: "piston 水平位置", value: state.piston.x, unit: 'm' });
out.push({ key: "piston.y", label: "piston 竖直位置", value: state.piston.y, unit: 'm' });
out.push({ key: "piston.vx", label: "piston 水平速度", value: (b.piston.x - a.piston.x) / dt, unit: 'm/s' });
out.push({ key: "piston.vy", label: "piston 竖直速度", value: (b.piston.y - a.piston.y) / dt, unit: 'm/s' });
return out;
